def choose_move(observation):
    def pair(v, default=(0, 0)):
        try:
            if isinstance(v, (list, tuple)) and len(v) >= 2:
                return int(v[0]), int(v[1])
        except Exception:
            pass
        return default

    def clamp_step(a, b):
        if b > a:
            return 1
        if b < a:
            return -1
        return 0

    def manhattan(p, q):
        return abs(p[0] - q[0]) + abs(p[1] - q[1])

    def best_by(items, score_fn, minimize=True):
        best_item = None
        best_score = None
        for item in items:
            try:
                s = score_fn(item)
            except Exception:
                continue
            if best_item is None:
                best_item, best_score = item, s
            else:
                if minimize and s < best_score:
                    best_item, best_score = item, s
                elif not minimize and s > best_score:
                    best_item, best_score = item, s
        return best_item

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pair(observation.get("self_position", (0, 0)))
    ox, oy = pair(observation.get("opponent_position", (sx, sy)))
    grid_w = int(observation.get("grid_width", 0) or 0)
    grid_h = int(observation.get("grid_height", 0) or 0)

    def toward(target):
        tx, ty = pair(target, (sx, sy))
        return [clamp_step(sx, tx), clamp_step(sy, ty)]

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return toward((ox, oy))
        corners = []
        if grid_w > 0 and grid_h > 0:
            corners = [(0, 0), (0, grid_h - 1), (grid_w - 1, 0), (grid_w - 1, grid_h - 1)]
        else:
            corners = [(-1, -1), (-1, 1), (1, -1), (1, 1)]
        target = best_by(corners, lambda c: manhattan(c, (ox, oy)), minimize=False)
        if target is None:
            target = (sx - clamp_step(ox, sx), sy - clamp_step(oy, sy))
        return toward(target)

    if env == "territory_control":
        candidates = []
        for key in ("unclaimed_cells", "opponent_territory", "frontier_cells", "targets"):
            vals = observation.get(key) or []
            if vals:
                candidates = vals
                break
        if not candidates:
            # drift toward opponent if nothing better
            return toward((ox, oy))
        target = best_by(candidates, lambda c: manhattan(pair(c, (sx, sy)), (sx, sy)), minimize=True)
        return toward(target if target is not None else (ox, oy))

    resources = observation.get("resources") or observation.get("resource_positions") or []
    if resources:
        target = best_by(resources, lambda c: manhattan(pair(c, (sx, sy)), (sx, sy)), minimize=True)
        if target is not None:
            return toward(target)

    # fallback: pursue opponent or stay safe
    if ox != sx or oy != sy:
        return toward((ox, oy))
    return [0, 0]

